<template>
    <div class="music-home">
        <el-autocomplete :fetch-suggestions="querySearch" :trigger-on-focus="false" placeholder="请输入内容" v-model="name">
            <el-button slot="append" @click="searchKey" icon="el-icon-search"></el-button>
        </el-autocomplete>
        
        
        <div class="demo-image">
            <div class="block" v-for="item, k in kuwolist" :key="k">
                <span class="demonstration" @click="payList(item.id)">{{ item.title }}</span>
            </div>
        </div>

        <div id="aplayer"></div>
        
        <el-drawer
        title="搜索结果"
        :visible.sync="drawer"
        :direction="direction"
        size="80%">
            
            <ul id="playlist" >
                <li v-for=" item, k  in addList " :key="k" >
                    <el-card shadow="hover">
                        {{k+1}} - {{item.title}}  
                        <div class="pay">
                            <i @click="playSong(k)" class="el-icon-video-play"></i>
                        </div>
                        <div class="author">
                            {{ item.author }}
                        </div>
                    </el-card>
                </li>
            </ul>
            
        </el-drawer>
        
        
    </div>
</template>
<script>
import APlayer from "aplayer";
import "aplayer/dist/APlayer.min.css";
import request from '../server/request';

export default {
    data() {
        return {
            drawer: false,
            direction: 'btt',
            name: '',
            kuwolist: [
                { 'title': '劲爆车载DJ', 'id': 3597551428, 'img': '' },
                { 'title': '2024抖音热门DJ歌曲', 'id': 3591310814, 'img': '' },
                { 'title': '抖音热门DJ舞曲 | 免费气氛组上线', 'id': 3181288040, 'img': '' },
                { 'title': '2020热门DJ嗨曲，一键开启提速模式', 'id': 3009338189, 'img': '' },
                { 'title': '情绪孤岛', 'id': 3595572047, 'img': '' },
                { 'title': '粤语私藏', 'id': 3369538162, 'img': '' },
                { 'title': '车载小情歌', 'id': 3286144492, 'img': '' },
                { 'title': '日语精选集', 'id': 3548494451, 'img': '' },
                { 'title': '通勤必备', 'id': 3467718194, 'img': '' },
                { 'title': '日系复古', 'id': 3563113106, 'img': '' },
                { 'title': '浪漫睡眠指南', 'id': 3572523053, 'img': '' },
                { 'title': '港台怀旧金曲', 'id': 3593745732, 'img': '' },
                { 'title': '经典老歌大放送！一人一首代表作！', 'id': 2996314807, 'img': '' },
                { 'title': '港台怀旧金曲丨7080年代经典老歌', 'id': 3593745732, 'img': '' },
                { 'title': '（怀旧）经典老歌，勾起了往事的回忆', 'id': 2429842898, 'img': '' },
                { 'title': '【经典伤感情歌】随风逝去的深情往事', 'id': 2831801142, 'img': '' },
                { 'title': '抖音热歌丨收听100首热播流行单曲', 'id': 3171455673, 'img': '' },

            ],
            netlist: [
                { 'title': '飙升榜', 'id': 19723756, 'img': '' },
                { 'title': '新歌榜', 'id': 3779629, 'img': '' },
                { 'title': '热歌榜', 'id': 3778678, 'img': '' },
                { 'title': '粤语经典', 'id': 8805180200, 'img': '' },
                { 'title': '影视经典', 'id': 8907175201, 'img': '' },
                { 'title': '粤语唱片行', 'id': 3455816, 'img': '' },
                { 'title': '武侠剧原声', 'id': 8182850834, 'img': '' },
                { 'title': '香港唱片商会销量榜', 'id': 9892674200, 'img': '' },
                { 'title': '粤语经典老歌', 'id': 8597656205, 'img': '' },
            ],
            musicList: [],
            addList:[],
            ap:'',
        }
    },
    mounted() {
        //this.loadAll();
        this.ap = new APlayer({
                container: document.getElementById('aplayer'),
                narrow: false,
                autoplay: false,
                showlrc: true,
                controls: true,
                theme: "#b7daff",
                loop:'all',
                // fixed:true,  //开启吸底模式
                lrcType: 3, // 可根据需要调整歌词类型
                volume: 0.7, //默认音量
                listFolded: true,
                //customAudioType:'normal',
        });
        this.dePay();
    },
    methods: {
        
        querySearch(queryString, cb) {
            try {
                const data = request.getData('/api/music?name='+this.name);
                data.then(result => {
                    const resultArray = result.map((datas) => ({
                        value:datas.name,
                        title: datas.name,
                        author: datas.artist,
                        url: datas.rid ? datas.url : "/api/api/music/payurl?id=" + datas.url_id,
                        pic: datas.rid ? datas.pic : '/api/api/music/pic?id=' + datas.pic_id,
                        lrc: datas.rid ? datas.lrc : '/api/api/music/lyric?id=' + datas.lyric_id,
                    }));
                    // 调用 callback 返回建议列表的数据
                    cb(resultArray);
                }).catch(error => {
                    console.error('出现错误:', error);
                });
            } catch (error) {
                console.error("获取音乐数据时出错:", error);
            }
        },
        
        handleSelect(item) {
            //console.log(item);
        },
        //搜索结果
        searchKey() {
            //清除所有空格
            const key = this.name.replace(/\s+/g, '');
            if (!key) {
                this.$message({
                    message: '请输入搜索关键字！！！',
                    type: 'warning',
                    showClose: true,
                });
                return false;
            }
            const loading = this.$loading({
                lock: true,
                text: 'Loading',
                spinner: 'el-icon-loading',
                background: 'rgba(0, 0, 0, 0.7)'
            });
            try {
                const data = request.getData('/api/music?name='+key);
                data.then(result => {
                    this.addList = result.map((datas) => ({
                        value: datas.name,
                        //type:'normal',
                        title: datas.name,
                        author: datas.artist,
                        url: datas.rid ? datas.url : "/api/api/music/payurl?id=" + datas.url_id,
                        pic: datas.rid ? datas.pic : '/api/api/music/pic?id=' + datas.pic_id,
                        lrc: datas.rid ? datas.lrc : '/api/api/music/lyric?id=' + datas.lyric_id,
                    }));
                    loading.close();
                    this.drawer = true;
                }).catch(error => {
                    console.error('出现错误:', error);
                });
            } catch (error) {
                console.error("获取音乐数据时出错:", error);
            }
        },
        //切换播放歌曲
        playSong(item) {
            this.ap.list.clear();
            this.ap.list.add(this.addList);
            this.ap.list.switch(item); //切换到播放的歌曲
            setTimeout(() => this.ap.play(), 500); // 延迟重试
            this.ap.list.show(); //显示播放列表
            this.ap.setMode('normal'); //播放器模式  'mini' 或 'normal'
            this.ap.lrc.show();
            this.drawer = false;  //关闭搜索结果
        },
        //初始播放列表数据
        dePay() {
            try {
                const data = request.getData('/api/music?type=rank');
                data.then(result => {
                    const resultArray = result;
                    this.musicList = resultArray.map((datas) => ({
                        title: datas.name,
                        //type:'normal',
                        author: datas.artist,
                        url: datas.rid ? datas.url : "/api/api/music/payurl?id=" + datas.url_id,
                        pic: datas.rid ? datas.pic : '/api/api/music/pic?id=' + datas.pic_id,
                        lrc: datas.rid ? datas.lrc : '/api/api/music/lyric?id=' + datas.lyric_id,
                    }));
                    this.ap.list.add(this.musicList);
                    this.ap.list.show(); //显示播放列表
                    //this.ap.play();
                }).catch(error => {
                console.error('出现错误:', error);
                });
            } catch (error) {
                console.error("获取音乐数据时出错:", error);
            }
        },
        payList(id) {
            const loading = this.$loading({
                lock: true,
                text: 'Loading',
                spinner: 'el-icon-loading',
                background: 'rgba(0, 0, 0, 0.7)'
            });
            try {
                const data = request.getData('/api/music/paylist?id='+id);
                data.then(result => {
                    const resultArray = result;
                    this.addList = resultArray.map((datas) => ({
                        title: datas.name,
                        //type:'normal',
                        author: datas.artist,
                        url: datas.rid ? datas.url : "/api/api/music/payurl?id=" + datas.url_id,
                        pic: datas.rid ? datas.pic : '/api/api/music/pic?id=' + datas.pic_id,
                        lrc: datas.rid ? datas.lrc : '/api/api/music/lyric?id=' + datas.lyric_id,
                    }));
                    loading.close();
                    this.drawer = true;
                    //this.ap.play();
                }).catch(error => {
                console.error('出现错误:', error);
                });
            } catch (error) {
                console.error("获取音乐数据时出错:", error);
            }
        }
    },
}
</script>>
<style scoped>

@media screen and (min-width: 960px) {
    .music-home {
        width: 35%;
        margin: auto;
    }
}
.pay{
    width: 30px;
    font-size: 32px;
    cursor:pointer;
    float:right;
}
.author{
    color:#796969;
    font-size:13px;
    margin-left:22px;
    padding-top:5px;
}

ul li{
    list-style: none;
    padding: 10px 0;
    text-align: left;
    max-width: 400px;
    margin: auto;
}
.block{
    cursor: pointer;
}
.el-autocomplete {
    position: relative;
    display: inline-block;
    width: 100%;
}
.demo-image .demonstration {
    display: block;
    color: #8492a6;
    font-size: 14px;
    margin-bottom: 20px;
}
.demo-image .block {
    padding: 10px 10px;
    text-align: center;
    border-right: 1px solid #eff2f6;
    display: inline-block;
    box-sizing: border-box;
    vertical-align: top;
}
</style>>