<template>
  <div>
    <div class="apl" id="aplayer"></div>
    <ul id="playlist"></ul>
    <div class="controls">
      <button @click="prevSong">上一首</button>
      <button @click="togglePlay">{{ isPlaying ? "暂停" : "播放" }}</button>
      <button @click="nextSong">下一首</button>
      <button @click="updatePlaylist">更新播放列表</button>
    </div>
  </div>
</template>

<script>
import APlayer from "aplayer";
import "aplayer/dist/APlayer.min.css";
import request from '../server/request';

export default {
  name: "MusicPlayer",
  data() {
    return {
      aplayer: null,
      musicList: [],
      currentSongIndex: 0, // 当前播放的歌曲索引
      isPlaying: false, // 播放状态
    };
  },
  mounted() {
    this.fetchMusicList("/api/music");
    
  },
  methods: {
    
    async fetchMusicList(url) {
      try {
        const data = request.getData(url);
        data.then(result => {
          const resultArray = result;
            this.musicList = resultArray.map((datas) => ({
            title: datas.name,
            author: datas.artist,
            url: datas.rid ? datas.url : "/api/api/music/payurl?id=" + datas.url_id,
            pic: datas.rid ? datas.pic : '/api/api/music/pic?id=' + datas.pic_id,
            lrc: datas.rid ? datas.lrc : '/api/api/music/lyric?id=' + datas.lyric_id,
            }));
            this.initializeAPlayer();
        }).catch(error => {
          console.error('出现错误:', error);
        });
      } catch (error) {
        console.error("获取音乐数据时出错:", error);
      }
    },
    initializeAPlayer() {
      const aplayerElement = document.getElementById("aplayer");
      if (aplayerElement) {
        this.aplayer = new APlayer({
          element: aplayerElement,
          narrow: false,
          autoplay: false,
          showlrc: true,
          theme: "#b7daff",
          loop:'all',
          //fixed:true,  //开启吸底模式
          music: this.musicList,
          lrcType: 3, // 可根据需要调整歌词类型
          volume:0.7 //默认音量
        });

        this.aplayer.on("play", () => {
          this.isPlaying = true;
        });

        this.aplayer.on("pause", () => {
          this.isPlaying = false;
        });

        this.aplayer.on("ended", () => {
          this.nextSong();
        });
        //this.updatePlaylistUI(); // 更新播放列表UI
      } else {
        console.error("APlayer 元素未找到。");
      }
    },
    
    
    togglePlay() {
      this.isPlaying ? this.aplayer.pause() : this.aplayer.play();
    },
    nextSong() {
      //下一首
      this.aplayer.skipForward();
      this.aplayer.play();
    },
    prevSong() {
      //上一首
      this.aplayer.skipBack();
      this.aplayer.play();
    },
    updatePlaylist() {
      this.fetchMusicList("/api/music/paylist");
      this.isPlaying = false;
    },
  },
};
</script>

<style scoped>
.apl {
  width: 100%;
}
.controls {
  margin-top: 10px;
}
button {
  margin-right: 10px;
  padding: 5px 10px;
}
</style>
